function canConstruct(ransomNote: string, magazine: string): boolean {
  // Букв в записке больше, чем в журнале, — точно не хватит
  if (ransomNote.length > magazine.length) return false;

  // Сколько раз каждая из 26 букв есть в журнале
  const count = new Array<number>(26).fill(0);
  for (let i = 0; i < magazine.length; i++) {
    count[magazine.charCodeAt(i) - 97]++;
  }

  // «Тратим» буквы на записку
  for (let i = 0; i < ransomNote.length; i++) {
    const idx = ransomNote.charCodeAt(i) - 97;
    count[idx]--;
    // Ушли в минус — этой буквы в журнале не хватает
    if (count[idx] < 0) return false;
  }

  return true;
}

// Время: O(m + n), где m и n — длины строк
// Память: O(1) — массив на 26 букв
